// Scatterplot Tour — Animation, route: jsx
// Source: scatterplot-tour
//
// Self-contained: every local import is inlined below. Requires only d3, motion, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useState } from 'react';
import * as d3 from 'd3';
import { motion } from 'motion/react';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from scatterplotTour ----
type TourPoint = { id: number; cls: number; dims: number[] };
type TourProjection = { name: string; x: number; y: number };

const dimensionNames = ['D1', 'D2', 'D3', 'D4', 'D5', 'D6'];
const classNames = ['Class A', 'Class B', 'Class C'];

/** Each projection is a different pair of dimensions, chosen so the structure genuinely changes. */
const projections: TourProjection[] = [
  { name: 'Three clusters', x: 0, y: 1 },
  { name: 'Linear correlation', x: 2, y: 4 },
  { name: 'Ring', x: 2, y: 3 },
  { name: 'Class bands', x: 3, y: 5 }
];

function mulberry32(seed: number): () => number {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function normal(rand: () => number, sigma: number): number {
  return Math.sqrt(-2 * Math.log(1 - rand())) * Math.cos(2 * Math.PI * rand()) * sigma;
}

const CLUSTER_CENTERS = [
  [Math.sqrt(3), 1],
  [-Math.sqrt(3), 1],
  [0, -2]
];

/** Seeded once at module load so the tour is byte-identical across reloads. */
function buildPoints(): TourPoint[] {
  const rand = mulberry32(20260813);
  const goldenAngle = Math.PI * (3 - Math.sqrt(5));

  return Array.from({ length: 240 }, (_, i) => {
    const cls = i % 3;
    const center = CLUSTER_CENTERS[cls];
    const d1 = center[0] + normal(rand, 0.42);
    const d2 = center[1] + normal(rand, 0.42);
    const angle = i * goldenAngle;
    const radius = 2.5 + normal(rand, 0.16);
    const d3 = Math.cos(angle) * radius;
    return {
      id: i,
      cls,
      dims: [
        d1,
        d2,
        d3,
        Math.sin(angle) * radius,
        0.95 * d3 + normal(rand, 0.3),
        (cls - 1) * 2.3 + normal(rand, 0.28)
      ]
    };
  });
}

const tourPoints: TourPoint[] = buildPoints();

const MARGIN = { top: 30, right: 20, bottom: 46, left: 52 };
const STEP_MS = 2600;
const TRAVEL_SEC = 1.3;
const Y_DOMAIN = 3.5;

/**
 * Points in an n-dimensional space, the named dimensions and classes they use, and the
 * pairs of dimension indices the tour cycles through.
 */
export type Data = {
  points: { id: number; cls: number; dims: number[] }[];
  projections: { name: string; x: number; y: number }[];
  dimensionNames: string[];
  classNames: string[];
};

const DEMO: Data = { points: tourPoints, projections, dimensionNames, classNames };

export default function ScatterplotTour({
  data = DEMO,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 0.75);
  const innerWidth = Math.max(1, width - MARGIN.left - MARGIN.right);
  const innerHeight = Math.max(1, height - MARGIN.top - MARGIN.bottom);
  const [step, setStep] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => setStep((s) => (s + 1) % data.projections.length), STEP_MS);
    return () => clearInterval(timer);
  }, [data]);

  const y = useMemo(
    () => d3.scaleLinear().domain([-Y_DOMAIN, Y_DOMAIN]).range([innerHeight, 0]),
    [innerHeight]
  );

  // Equal units per pixel on both axes, so the ring projection stays a circle.
  const x = useMemo(() => {
    const half = (Y_DOMAIN * innerWidth) / innerHeight;
    return d3.scaleLinear().domain([-half, half]).range([0, innerWidth]);
  }, [innerWidth, innerHeight]);

  const color = useMemo(
    () => d3.scaleOrdinal<string, string>().domain(data.classNames).range(d3.schemeObservable10),
    [data]
  );

  const xTicks: Tick[] = useMemo(
    () => x.ticks(8).map((v) => ({ value: String(v), offset: x(v) })),
    [x]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(7).map((v) => ({ value: String(v), offset: y(v) })),
    [y]
  );

  const projection = data.projections[step];

  const placed = useMemo(
    () =>
      data.points.map((p) => ({
        id: p.id,
        cls: p.cls,
        cx: x(p.dims[projection.x]),
        cy: y(p.dims[projection.y])
      })),
    [data, x, y, projection]
  );

  if (width === 0) return null;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label="Animated tour of a six dimensional dataset, cycling through four two dimensional projections">
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />

        <g className="axis">
          {xTicks.map(({ value, offset }) => (
            <line key={value} className="grid" x1={offset} x2={offset} y1={0} y2={innerHeight} />
          ))}
        </g>

        <g>
          {placed.map((p) => (
            <motion.circle
              key={p.id}
              r={3}
              fill={color(data.classNames[p.cls])}
              fillOpacity={0.8}
              initial={false}
              animate={{ cx: p.cx, cy: p.cy }}
              transition={{ duration: TRAVEL_SEC, ease: 'easeInOut' }}
            />
          ))}
        </g>

        <g className="axis">
          <text x={innerWidth} y={innerHeight + MARGIN.bottom - 8} textAnchor="end">
            {data.dimensionNames[projection.x]} →
          </text>
          <text x={-MARGIN.left} y={-10} textAnchor="start">
            ↑ {data.dimensionNames[projection.y]}
          </text>
        </g>

        <text x={innerWidth / 2} y={-10} textAnchor="middle" fill="var(--text)" fontSize={13}>
          {projection.name}
        </text>

        <g
          transform={`translate(${innerWidth / 2 - (data.projections.length - 1) * 6},${
            innerHeight + 34
          })`}
        >
          {data.projections.map((p, i) => (
            <circle
              key={p.name}
              cx={i * 12}
              cy={0}
              r={3}
              fill={i === step ? 'var(--accent)' : 'var(--line)'}
            />
          ))}
        </g>

        <g className="axis" transform="translate(8,4)">
          {data.classNames.map((name, i) => (
            <g key={name} transform={`translate(0,${i * 16})`}>
              <circle cx={0} cy={0} r={4} fill={color(name)} />
              <text x={10} dy="0.32em" textAnchor="start">
                {name}
              </text>
            </g>
          ))}
        </g>
      </g>
    </svg>
  );
}
